insert into public.services (id,sort,data) values ('svc-1',0,'{"id":"svc-1","icon":"fa-solid fa-house-chimney","title":"Property Buying Assistance","desc":"Support through the whole purchase — from choosing a property to understanding what is required of you at each step.","bullets":["Shortlisting properties that fit your brief","Walking through what a listing includes","Coordinating with you on requirements and timelines","A single point of contact from inquiry to decision"]}'::jsonb) on conflict (id) do update set sort=excluded.sort, data=excluded.data;
insert into public.services (id,sort,data) values ('svc-2',1,'{"id":"svc-2","icon":"fa-solid fa-chart-line","title":"Property Investment Guidance","desc":"For buyers looking at property as an investment rather than a residence, guidance on how the available options compare.","bullets":["Comparing options across the areas we serve","Clarity on payment terms as published by the project","Discussion of what suits your holding plans","Straight answers on what is and is not confirmed"]}'::jsonb) on conflict (id) do update set sort=excluded.sort, data=excluded.data;
insert into public.services (id,sort,data) values ('svc-3',2,'{"id":"svc-3","icon":"fa-solid fa-house","title":"House & Lot / Residential Property Assistance","desc":"Dedicated help for buyers looking at residential house and lot properties in Iloilo, Tagaytay, Antipolo, Cavite and Binondo.","bullets":["Residential listings in the areas we serve","Details on layout, features and inclusions","Help comparing units within a project","Support arranging the next step"]}'::jsonb) on conflict (id) do update set sort=excluded.sort, data=excluded.data;
insert into public.services (id,sort,data) values ('svc-4',3,'{"id":"svc-4","icon":"fa-solid fa-magnifying-glass-location","title":"Property Matching","desc":"Rather than sending you everything, we narrow the field to the properties that actually answer your brief.","bullets":["Matching on location, type and budget range","Shortlists you can review at your own pace","Adjusting the search as your priorities change","New options flagged as they become available"]}'::jsonb) on conflict (id) do update set sort=excluded.sort, data=excluded.data;
insert into public.services (id,sort,data) values ('svc-5',4,'{"id":"svc-5","icon":"fa-solid fa-eye","title":"Site Viewing / Consultation","desc":"See a property in person, or talk it through first — whichever you prefer, arranged at a time that works for you.","bullets":["Site viewing arranged on request","Consultation by call, text or Messenger","Questions answered before you commit to a visit","Follow-up after the viewing"]}'::jsonb) on conflict (id) do update set sort=excluded.sort, data=excluded.data;
insert into public.services (id,sort,data) values ('svc-6',5,'{"id":"svc-6","icon":"fa-solid fa-comments","title":"Buyer Inquiry Assistance","desc":"Every question, from the first one to the last, answered by a real person who knows your file.","bullets":["Direct replies by call, text or Messenger","Help understanding documents and terms","Follow-up on outstanding questions","Continuity — the same contact throughout"]}'::jsonb) on conflict (id) do update set sort=excluded.sort, data=excluded.data;
insert into public.site_content (key,data) values ('about','{"kicker":"Our story","headline":"Guiding You Home, Building Your Future","paragraph1":"Buying property is rarely a simple transaction. There are locations to compare, documents to understand, viewings to arrange and questions that are hard to ask a stranger. Dream Home Navigators exists to make that process feel manageable.","paragraph2":"We work as the point of contact between buyers and the properties available in the areas we serve. That means shortlisting homes that match what you asked for, explaining what each listing actually includes, arranging site viewings, and staying reachable while you decide. Our name is the promise: we navigate, you decide. Whether the property is a first family home or an investment you are weighing carefully, the work is the same — get you accurate information, and give you room to make the call.","mission":"To help every client find a property that fits their life and their plans — guided by clear information, honest advice and steady support from the first inquiry to the final decision.","vision":"Guiding You Home, Building Your Future.","whyUs":["Straight information — We work from what is actually documented about a property. Where a detail has not been confirmed, we say so rather than filling the gap with a guess.","Guidance, not pressure — The goal is a property that fits your plans. That means honest answers about what suits you — and what does not.","Available when it matters — Buying property runs on timing. Questions get answered by call, text or Messenger so you are never left waiting.","Focused on five areas — Iloilo, Tagaytay, Antipolo, Cavite and Binondo — we concentrate on the locations we know rather than spreading thin.","Buyers and investors alike — Whether you are looking for a family home or weighing a property as an investment, the assistance is shaped around your goal.","Easy to reach — Call, text or send a message on Messenger. Questions get a direct answer from a real person."]}'::jsonb) on conflict (key) do update set data=excluded.data;
insert into public.site_content (key,data) values ('featured','{"id":"ongpin-tower"}'::jsonb) on conflict (key) do update set data=excluded.data;
